    while num > 0:
        digit = num % 10
        if digit != 4 and digit != 7:
            return False
        num //= 10
    return num == 4 or num == 7

def is_nearly_lucky(num):
    count = 0
    while num > 0:
        digit = num % 10
        if digit == 4 or digit == 7:
            count += 1
        num //= 10
    return is_lucky(count)

